mapper.select:
select mn.* , mr.mr_serial_number as mrSerialNumber,mr.Mr_Report_Amount_Pre as mrReportAmountPre
, sc.C_NAME as constructionUnitName
, sc2.C_NAME as auditUnitName
, sc3.C_NAME as constructionContractorName
, mr.P_NAME as pName
from construction_completion_confirm mn
left join maintenance_record mr on mr.mr_id = mn.mr_id
left join sys_company sc on sc.C_ID = mn.Construction_Unit
left join sys_company sc2 on sc2.C_ID = mn.Audit_Unit
left join sys_company sc3 on sc3.C_ID = mn.Construction_Contractor
${params.authSql}

    and mn.id = #{params.id}


    and mn.mr_id = #{params.mrId}


    and mr.mr_serial_number like concat('%',#{params.mrSerialNumber},'%')


    and mn.confirm_serial_number like concat('%',#{params.confirmSerialNumber},'%')


    and mn.construction_site like concat('%',#{params.constructionSite},'%')


    and mn.construction_unit = #{params.constructionUnit}


    and sc.C_NAME like concat('%',#{params.constructionUnitName},'%')


    and mn.audit_unit = #{params.auditUnit}


    and sc2.C_NAME like concat('%',#{params.auditUnitName},'%')


    and mn.construction_contractor = #{params.constructionContractor}


    and sc3.C_NAME like concat('%',#{params.constructionContractorName},'%')


    and mn.state = #{params.state}


    and mn.Create_Time between #{params.createTimeRange[0]} and #{params.createTimeRange[1]}


    and mn.id not in (select distinct sad.completion_Confirm_Id
    from inv_settlement_apply_dtl sad
    left join inv_settlement_apply sa on sa.Sa_Id=sad.isa_id
    where sa.Sa_State!=3)


    and mr.P_NAME like concat('%',#{params.pName},'%')


    
        order by mn.${params.sortFiled} ${params.sortType}
    
    
        order by ${params.sortSideFiled} ${params.sortType}
    
    
        order by mn.Create_Time desc
